import{_ as a,o as t,c as o,ab as s}from"./chunks/framework.DfnUYNhO.js";const h=JSON.parse('{"title":"Transportes actuales y restricciones de plataforma","description":"","frontmatter":{"title":"Transportes actuales y restricciones de plataforma","docId":"developer.transports","translationKey":"developer.transports","locale":"es","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a5fcd19211bdd279a0696cde31c26cc7444a128e50c3ca752489b25acb7cd9a","translationRevision":"15e858773e746822b7f728503f4ecb7de0b01bff30aadc52426dbc9470470f02","order":200},"headers":[],"relativePath":"es/developer/transports.md","filePath":"es/developer/transports.md","lastUpdated":1795476229000}'),r={name:"es/developer/transports.md"};function i(n,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Transportes actuales y restricciones de plataforma <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to &quot;Transportes actuales y restricciones de plataforma {#current-transports-and-platform-restrictions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Selecciona el transporte que existe en la compilación y plataforma de destino. Lee <a href="./control-api.html">Control API</a> y <a href="./collaboration.html">colaboración</a>. Un transporte lleva operaciones serializadas; no debe crear otro núcleo ni otorgar autoridad por sí mismo.</p><h2 id="choose-the-boundary" tabindex="-1">Elegir el límite <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to &quot;Elegir el límite {#choose-the-boundary}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recorrido</th><th>Implementación actual</th><th>Límite importante</th></tr></thead><tbody><tr><td>Escritorio WebView</td><td>IPC de Wry y cliente de control compartido</td><td>El ciclo de GUI/hilos pertenece al escritorio</td></tr><tr><td>CLI local</td><td>Socket Unix o tubería con nombre de Windows; host stdio explícito</td><td>Misma carpeta y propietario de la aplicación</td></tr><tr><td>Navegador local</td><td>Adaptador loopback nativo más <code>browser-transport.ts</code></td><td>Host nativo emparejado, no un servidor remoto público</td></tr><tr><td>Pasarela HTTPS/WSS autenticada</td><td>Transportes SDK/navegador con TLS, saludo, permisos y feature gates</td><td>Los comandos remotos necesitan un permiso explícito</td></tr><tr><td>Plugin de control remoto instalable</td><td><code>tiktools.remote-control</code> sobre un relay WSS con <code>remote.controller.ticket</code></td><td>Propiedad del plugin; el host no compila código remoto</td></tr></tbody></table><p>La interfaz TypeScript está en <code>src/web/shared/api/control-transport.ts</code>. El control remoto es un plugin instalable, no parte del binario del host: cada comando pasa por <code>HostCallPolicy</code> (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>). Esta compilación no tiene transporte peer/RTC nativo ni enlace de host de Cloud Teams.</p><h2 id="inspect-the-selected-route" tabindex="-1">Inspeccionar la ruta seleccionada <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to &quot;Inspeccionar la ruta seleccionada {#inspect-the-selected-route}&quot;">​</a></h2><p>Descubre los métodos y capacidades admitidos por el host conectado antes de emparejar o mostrar una acción de control:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span></code></pre></div><p>El emparejamiento y los permisos son propiedad del plugin: el ticket de controlador es de corta duración y un solo uso, y <code>remote.grant.list</code> / <code>remote.grant.revoke</code> son la vista autorizada. Una conexión de relay solo demuestra transporte, nunca autoridad RPC.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>El IPC local y el transporte de escritorio son rutas establecidas. El control remoto funciona mediante el plugin instalable y un relay autenticado; no es un segundo runtime de host. Los códigos de inicio de sesión se envían a los dispositivos conectados con una validez de cinco minutos, con OAuth como alternativa cuando no hay cuenta configurada. El IPC local en Android funciona con las herramientas instrumentadas <code>mobile</code> (<code>info</code> / <code>exec</code> / <code>tty</code>); los addons nativos y WebViews de escritorio siguen sin estar disponibles allí.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Trata la desconexión como incertidumbre posible para operaciones aceptadas. La reconexión debe invalidar proyecciones privadas, renegociar la identidad y reanudar o capturar flujos limitados. Nunca debilites la verificación de certificados ni vuelvas silenciosamente a un propietario local tras un fallo remoto. Los tickets caducados y los permisos revocados deben fallar en cerrado.</p><h2 id="operational-details" tabindex="-1">Detalles operativos <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles operativos {#operational-details}&quot;">​</a></h2><p>Mantén los permisos con el mínimo privilegio y plazo limitado; vuelve a comprobarlos tras cada reconexión. Diagnostica por separado identidad, caducidad del ticket, alcance del permiso, alcance del relay y tamaño de trama. Las tramas grandes fallan en la validación de encuadre, no producen RPC parciales. Prueba sesiones modificadas o revocadas con fixtures antes de la aceptación real con dos dispositivos.</p>`,16)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
